package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.ObjectCodec;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.ByteQuadsCanonicalizer;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.*;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.io.InputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class UTF8StreamJsonParser__releaseBuffers_TriageGen2Test {

    private IOContext mockIoContext;
    private ObjectCodec mockCodec;
    private InputStream mockInputStream;
    private ByteQuadsCanonicalizer mockSym;
    private Method releaseBuffersMethod;

    @Before
    public void setUp() throws Exception {
        mockIoContext = mock(IOContext.class);
        mockCodec = mock(ObjectCodec.class);
        mockInputStream = mock(InputStream.class);
        mockSym = mock(ByteQuadsCanonicalizer.class);

        // Access the protected method via reflection
        releaseBuffersMethod = UTF8StreamJsonParser.class.getDeclaredMethod("_releaseBuffers");
        releaseBuffersMethod.setAccessible(true);
    }

    /**
     * Helper to instantiate the parser using reflection since the constructor 
     * parameters are specific and internal.
     */
    private UTF8StreamJsonParser createParser(IOContext ctxt, byte[] inputBuffer, boolean bufferRecyclable) throws Exception {
        return new UTF8StreamJsonParser(
                ctxt,
                0,
                mockInputStream,
                mockCodec,
                mockSym,
                inputBuffer,
                0,
                0,
                bufferRecyclable
        );
    }

    /**
     * Test Case 1: bufferRecyclable is true and inputBuffer is not null.
     * Covers: if (_bufferRecyclable) { if (buf != null) { ... } }
     */
    @Test
    public void testReleaseBuffers_RecyclableAndBufferNotNull() throws Exception {
        byte[] buffer = new byte[10];
        UTF8StreamJsonParser parser = createParser(mockIoContext, buffer, true);

        releaseBuffersMethod.invoke(parser);

        // Verify symbols released
        verify(mockSym).release();
        // Verify buffer released via IOContext
        verify(mockIoContext).releaseReadIOBuffer(buffer);

        // Verify internal field _inputBuffer is null via reflection
        Field inputBufferField = UTF8StreamJsonParser.class.getDeclaredField("_inputBuffer");
        inputBufferField.setAccessible(true);
        assert(inputBufferField.get(parser) == null);
    }

    /**
     * Test Case 2: bufferRecyclable is true but inputBuffer is null.
     * Covers: if (_bufferRecyclable) { if (buf == null) { (skip) } }
     */
    @Test
    public void testReleaseBuffers_RecyclableAndBufferNull() throws Exception {
        UTF8StreamJsonParser parser = createParser(mockIoContext, null, true);

        releaseBuffersMethod.invoke(parser);

        // Verify symbols released
        verify(mockSym).release();
        // Verify no attempt to release null buffer
        verify(mockIoContext, never()).releaseReadIOBuffer(any());
    }

    /**
     * Test Case 3: bufferRecyclable is false.
     * Covers: if (_bufferRecyclable) { (skip) }
     */
    @Test
    public void testReleaseBuffers_NotRecyclable() throws Exception {
        byte[] buffer = new byte[10];
        UTF8StreamJsonParser parser = createParser(mockIoContext, buffer, false);

        releaseBuffersMethod.invoke(parser);

        // Verify symbols released regardless of recyclability
        verify(mockSym).release();
        // Verify buffer is NOT released because recyclable is false
        verify(mockIoContext, never()).releaseReadIOBuffer(any());

        // Verify buffer remains in the parser (not set to null)
        Field inputBufferField = UTF8StreamJsonParser.class.getDeclaredField("_inputBuffer");
        inputBufferField.setAccessible(true);
        assert(inputBufferField.get(parser) == buffer);
    }

    /**
     * Test Case 4: Verify Exception propagation.
     * Since _releaseBuffers throws IOException, we ensure that if the super or 
     * internal logic throws, it propagates.
     */
    @Test(expected = Exception.class)
    public void testReleaseBuffers_ThrowsException() throws Exception {
        // To simulate an exception in the flow, we can mock the symbol release to throw
        doThrow(new IOException("Simulated error")).when(mockSym).release();

        UTF8StreamJsonParser parser = createParser(mockIoContext, new byte[10], true);

        releaseBuffersMethod.invoke(parser);
    }
}
